.mobile-menu-card-gradient small,
.mobile-menu-card-compact small {
    color: #6b4b76 !important;
    text-shadow: none !important;
    font-weight: 800 !important;
}

/* Ajuste para que el menú respire mejor en fondo blanco */
.mobile-menu-grid-full {
    background: transparent !important;
}

/* Quitar cualquier fondo negro/morado anterior-full {
    background: transparent !important;
