/* Quitar cualquier fondo negro/morado anterior dentro del panel */
.mobile-menu-panel-full::before,
.mobile-menu-panel-full::after,
.mobile-menu-gradient-panel::before,
.mobile-menu-gradient-panel::after {
    display: none !important;
